# Run this script in the base path of DiffSynth-Studio:
# PYTHONPATH="./" bash examples/flux2/model_training/special/opd/train_FLUX.2-klein-base-4B-8steps_full.sh

# Download datasets
modelscope download --dataset DiffSynth-Studio/diffsynth_example_dataset --include "flux2/FLUX.2-klein-base-4B/*" --local_dir ./data/diffsynth_example_dataset

# Calculate the sigmas and timesteps, and fill them into the script below.
python examples/flux2/model_training/special/opd/compute_sigmas.py --scheduler_name "FLUX.2" --num_inference_steps 50 --extra_kwargs '{"dynamic_shift_len": 4096}'
python examples/flux2/model_training/special/opd/compute_sigmas.py --scheduler_name "FLUX.2" --num_inference_steps 8 --extra_kwargs '{"dynamic_shift_len": 4096}'

